{
  "type": "object",
  "description": "One authored test step (the unified test model). `kind` discriminates: `prompt` is a user message (model turn); `toolCall` is a deterministic, model-free tool call; `interact` is one pure widget action; `assert` is an assertion (a `Predicate` like `toolCalledWith` / `widgetRendered`, or a DOM `WidgetAssertion`).",
  "required": [
    "id",
    "kind"
  ],
  "properties": {
    "id": {
      "type": "string",
      "minLength": 1
    },
    "kind": {
      "type": "string",
      "enum": [
        "prompt",
        "toolCall",
        "interact",
        "assert"
      ]
    },
    "prompt": {
      "type": "string",
      "description": "User message (`kind: prompt`)."
    },
    "serverName": {
      "type": "string",
      "description": "Server that owns the tool (`kind: toolCall`)."
    },
    "toolName": {
      "type": "string",
      "description": "Tool name (`kind: toolCall` / `interact`)."
    },
    "arguments": {
      "type": "object",
      "description": "Tool-call arguments (`kind: toolCall`).",
      "additionalProperties": true
    },
    "action": {
      "type": "object",
      "description": "Widget action (`kind: interact`).",
      "additionalProperties": true
    },
    "assertion": {
      "type": "object",
      "description": "The rule an `assert` step checks (`kind: assert`). NOT a narrower spelling of a case's `checks`: this is `WidgetAssertion | Predicate`, and that union is why the field is called an assertion rather than a check. A `Predicate` is evaluated against the PERSISTED transcript, so a stored run can be re-graded against it months later; a `WidgetAssertion` is evaluated against a LIVE DOM and can never be replayed. Calling this a check would promise the replayability only one half of it has.",
      "additionalProperties": true
    }
  },
  "additionalProperties": true
}
{
  "type": "object",
  "properties": {
    "type": {
      "type": "string",
      "const": "toolCalledWith"
    },
    "toolName": {
      "type": "string",
      "minLength": 1
    },
    "args": {
      "type": "object",
      "properties": {
        "args": {
          "type": "object",
          "propertyNames": {
            "type": "string"
          },
          "additionalProperties": {}
        },
        "argumentMatching": {
          "type": "string",
          "enum": [
            "exact",
            "partial",
            "ignore"
          ]
        }
      },
      "required": [
        "args"
      ]
    },
    "minCount": {
      "type": "integer",
      "exclusiveMinimum": 0,
      "maximum": 9007199254740991
    },
    "role": {
      "type": "string",
      "enum": [
        "gating",
        "advisory",
        "required"
      ]
    },
    "severity": {
      "type": "string",
      "const": "warn"
    }
  },
  "required": [
    "type",
    "toolName",
    "args"
  ]
}
{
  "type": "object",
  "description": "A tool result in scope (every result, or only toolName's) whose content matches EVERY pattern (all within one result) occurred at least min (default 1) and at most max times. min and max count MATCHING results, not all results: min 0, max 0 means no result matches. The content is the result's text, then structuredContent, then its JSON output part (JSON as canonical JSON), or, with path, the value at that key in structuredContent (in the JSON output part when there is no structuredContent). isError results are included. A result whose text was truncated for storage (when path is omitted), or whose subject exceeds 100000 characters, is unreadable; so are results an incomplete capture did not record. A verdict they could decide is unscored.",
  "properties": {
    "type": {
      "type": "string",
      "const": "toolResultMatches"
    },
    "toolName": {
      "description": "Omit to read every tool's results.",
      "type": "string",
      "minLength": 1
    },
    "patterns": {
      "description": "Every pattern must match the same result. Use alternation (A|B) inside one pattern for either.",
      "minItems": 1,
      "maxItems": 8,
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1,
        "maxLength": 512
      }
    },
    "flags": {
      "description": "Applies to every pattern: i (ignore case), m (multiline), s (dot matches newline).",
      "type": "string",
      "enum": [
        "i",
        "m",
        "s",
        "im",
        "is",
        "ms",
        "ims"
      ]
    },
    "path": {
      "description": "JSON Pointer (RFC 6901) to ONE top-level key of structuredContent (of the JSON output part when there is no structuredContent), such as /elements; inside the key, ~1 stands for / and ~0 for ~. Omit to match the whole result. A result without the key does not match.",
      "type": "string",
      "minLength": 2,
      "maxLength": 257,
      "pattern": "^\\/(?:[^/~]|~[01])+$"
    },
    "min": {
      "description": "Minimum number of MATCHING results (default 1). min 0 requires max.",
      "type": "integer",
      "minimum": 0,
      "maximum": 9007199254740991
    },
    "max": {
      "description": "Maximum number of MATCHING results; at least min (or 1 when min is omitted).",
      "type": "integer",
      "minimum": 0,
      "maximum": 9007199254740991
    },
    "role": {
      "type": "string",
      "enum": [
        "gating",
        "advisory",
        "required"
      ]
    },
    "severity": {
      "type": "string",
      "const": "warn"
    }
  },
  "required": [
    "type",
    "patterns"
  ]
}
